                "topic": "Section I: Part A (No Calculator)",
                "difficulty": "medium",
                "question": "<p>Let <em>f</em> be a function defined by <img src=\"images/eb1d7f2d3009434c920b5fe9767cd73f.png\" class=\"exam-img\" style=\"max-width:100%; vertical-align:middle; margin:4px 0;\">. <em>f'</em>(2) =</p>",
                "options": [
                    "<img src=\"images/3c06f15117024b72b30d75f6379f1e9f.png\" class=\"exam-img\" style=\"max-width:100%; vertical-align:middle; margin:4px 0;\">",
                    "<img src=\"images/baad35a0a0c04724a44715d836bf8a0c.png\" class=\"exam-img\" style=\"max-width:100%; vertical-align:middle; margin:4px 0;\">",
                    "<img src=\"images/656707a2818245d38234cbc0a5441605.png\" class=\"exam-img\" style=\"max-width:100%; vertical-align:middle; margin:4px 0;\">",
                    "<img src=\"images/aaa9eda3b8704bfdbd28a3a2060c72ca.png\" class=\"exam-img\" style=\"max-width:100%; vertical-align:middle; margin:4px 0;\">"
                ],
